CREATE TABLE property_insurance_rates (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, percentage DECIMAL(6,5) NOT NULL, effective_year INTEGER NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW()); INSERT INTO property_insurance_rates (percentage, effective_year) VALUES (0.0280, 2024); ALTER TABLE property_insurance_rates ENABLE ROW LEVEL SECURITY; CREATE POLICY "Allow read access for all authenticated users" ON property_insurance_rates FOR SELECT TO authenticated USING (true); CREATE POLICY "Allow full access for service_role" ON property_insurance_rates FOR ALL TO service_role USING (true) WITH CHECK (true);
